// ===================== TASK GENERATOR =====================
const identifyTaskDB=[{"s":"Su significado no queda cerrado nunca.","type":"Concepto esencialmente disputado (Gallie, 1956)"},{"s":"Que nadie me estorbe.","type":"Libertad negativa (Berlin, 1958)"},{"s":"Poder de verdad hacer.","type":"Libertad positiva (Berlin, 1958)"},{"s":"Un arreglo de conceptos en tres capas.","type":"La morfología (Freeden, 1996)"},{"s":"Lo que no se puede quitar sin que deje de ser eso.","type":"El núcleo"},{"s":"Los conceptos que precisan el núcleo.","type":"Los adyacentes"},{"s":"Lo que cambia con el lugar y con la década.","type":"Los periféricos"},{"s":"Fijarle un solo sentido y venderlo como obvio.","type":"La descontestación"},{"s":"Tres textos que no se parezcan, uno por página.","type":"La práctica del módulo"},{"s":"Si el núcleo no lo firmaría nadie de esa familia.","type":"Se dibujó un muñeco: se rehace"}];
const classifyTaskDB=[{"w":"W. B. Gallie","gen":"Fuente","n":"Los conceptos esencialmente disputados","g":"«Essentially Contested Concepts», 1956","t":"Clásico sólido de la filosofía"},{"w":"Isaiah Berlin","gen":"Fuente","n":"Las dos libertades","g":"«Dos conceptos de libertad», 1958","t":"Clásico sólido, fuente canónica del ejemplo"},{"w":"Michael Freeden (1996)","gen":"Fuente","n":"La morfología y la descontestación","g":"«Ideologies and Political Theory»","t":"Académico sólido, base del análisis"},{"w":"Freeden (2003)","gen":"Fuente","n":"La rampa de entrada, corta y seria","g":"«Ideology: A Very Short Introduction»","t":"Del propio dueño del instrumento"},{"w":"Libertad negativa","gen":"Concepto","n":"Que nadie me estorbe","g":"Se guarda estándose quieto","t":"Una de las dos mitades de Berlin"},{"w":"Libertad positiva","gen":"Concepto","n":"Poder de verdad hacer","g":"No se alcanza sin que alguien mueva algo","t":"La otra mitad de Berlin"},{"w":"Núcleo","gen":"Capa","n":"Lo que no se negocia","g":"Prueba: quítalo y mira si sigue siendo eso","t":"Primera capa de la morfología"},{"w":"Adyacentes","gen":"Capa","n":"Lo que precisa el núcleo","g":"Se discute cuál, pero alguno hace falta","t":"Segunda capa"},{"w":"Periféricos","gen":"Capa","n":"Decorado de temporada","g":"Cambia con el lugar y la década","t":"Tercera capa"},{"w":"Descontestación","gen":"Movimiento","n":"El cierre vendido como sentido común","g":"Lo hace toda ideología","t":"La señal que hay que aprender a ver"}];
const completeTaskDB=[{"s":"Hay conceptos esencialmente ___.","opts":["disputados","olvidados","traducidos"],"ans":"disputados"},{"s":"La disputa es su modo de ___.","opts":["existir","fallar","terminar"],"ans":"existir"},{"s":"La libertad negativa pide que nadie me ___.","opts":["estorbe","ayude","mire"],"ans":"estorbe"},{"s":"La libertad positiva es poder de verdad ___.","opts":["hacer","callar","pedir"],"ans":"hacer"},{"s":"Un ideario es una ___ de conceptos.","opts":["morfología","lista","pila"],"ans":"morfología"},{"s":"La capa intocable es el ___.","opts":["núcleo","borde","adorno"],"ans":"núcleo"},{"s":"El decorado de temporada es la ___.","opts":["periferia","raíz","base"],"ans":"periferia"},{"s":"Cerrar un concepto abierto y venderlo como obvio es la ___.","opts":["descontestación","definición","aclaración"],"ans":"descontestación"}];
const explainQuestions=[{"q":"¿Qué es un concepto esencialmente disputado y por qué su disputa no es un defecto? Explícalo con el caso de los dos vecinos y la calle.","ans":"Es un concepto cuyo significado no queda cerrado nunca, como libertad, igualdad, justicia o democracia; lo nombró W. B. Gallie en 1956. Su disputa no es un defecto del idioma ni pereza de los diccionarios: es su modo de existir, porque el concepto solo funciona mientras admite versiones rivales que compiten por él. El caso de la calle lo enseña sin teoría: dos vecinos firmaron la misma carta pidiendo libertad, uno quería topes para que sus hijos pudieran salir y el otro quería que nadie le dijera a qué velocidad manejar. Ninguno mintió y ninguno se equivocó de palabra: los dos usaron la palabra correcta, y la palabra admitía las dos cosas. Por eso el remedio no es definir mejor de una vez para siempre, sino preguntar en cuál de sus sentidos la está usando cada uno."},{"q":"Explica las dos libertades de Berlin (1958) y por qué media pelea política del siglo cabe en cuál de las dos se nombra.","ans":"Libertad negativa es que nadie me estorbe: se conserva si nadie interviene, y por eso se protege con límites al poder. Libertad positiva es poder de verdad hacer: no se alcanza sin que alguien mueva algo, y por eso se persigue con recursos, instituciones o reglas. Berlin las separó en su lección de Oxford de 1958, y la separación explica discusiones enteras que parecían de mala fe: cuando un lado dice que el otro está contra la libertad, casi siempre está diciendo que está contra la suya. La pelea del siglo veinte entre bloques se lee así: los dos decían defender la libertad, cada uno hablaba de una de las dos mitades, y cada uno acusaba al otro de no tener ninguna. Nombrar cuál de las dos se está pidiendo no acaba el desacuerdo, pero lo vuelve un desacuerdo real y por tanto negociable."},{"q":"¿Qué son el núcleo, los adyacentes y los periféricos, y cómo se distinguen en la práctica?","ans":"Son las tres capas de la morfología de Freeden (1996). El núcleo es lo que no se negocia sin dejar de ser esa ideología, y se encuentra con una prueba, no leyendo el orden del documento: se le quita, y si el ideario sigue siendo el mismo, no era núcleo. Los adyacentes son los conceptos que precisan el núcleo y le dan forma concreta; se puede discutir cuál se elige, pero alguno hace falta, porque un núcleo solo es demasiado vago para decidir nada. Los periféricos son lo que cambia con el lugar y con la década, el decorado de temporada, y se pueden cambiar sin que nadie deje de ser lo que era. La utilidad práctica es inmediata: casi todas las peleas ocurren en la periferia y se pelean como si fueran el núcleo, y al mismo tiempo el núcleo suele negociarse sin que nadie note que se está tocando."},{"q":"¿Qué es la descontestación y cómo se detecta en un texto real?","ans":"Es el movimiento que hace toda ideología: tomar un concepto disputado, fijarle un solo significado como si fuera el único posible, y vender ese cierre como sentido común. El liberalismo lo hace con libertad, cerrándola como no interferencia o como autonomía; el socialismo lo hace con igualdad, llevándola más allá de la igualdad ante la ley. Se detecta con dos señales y una prueba. Señal uno: el texto usa el concepto sin decir en qué sentido. Señal dos: da por hecho que su sentido es el obvio, y no menciona que hubo alternativa. La prueba de los tres segundos: se pone el otro significado en la misma frase, sin tocar nada más. Si la frase se vuelve absurda o cambia de bando, había un cierre escondido, y ese cierre era la afirmación de verdad del texto."},{"q":"¿Por qué el entrenamiento de esta etapa usa textos históricos o de fuera, y no documentos políticos de hoy?","ans":"Por una regla de la casa que no se negocia: cero partidismo hondureño actual, y a ningún político vivo del país se le reparte etiqueta. La razón no es cobardía sino calibración. Un documento que todavía puede ganar o perder una elección se disecciona con el pulso torcido, porque el que corta ya sabe qué quiere encontrar y la familia entera lo lee como un golpe. Un plan de gobierno de hace décadas, la declaración de principios de una organización o el «quiénes somos» de una empresa cualquiera se dejan diseccionar sin que nadie se sienta atacado, y por tanto enseñan el instrumento en vez de servir de arma. Y hay un beneficio extra: quien aprende con textos viejos llega entrenado al texto de hoy, y entonces el análisis vale, porque el instrumento no nació torcido."},{"q":"¿Por qué la etapa obliga a dibujar la morfología propia, y qué señal indica que un dibujo ajeno salió mal?","ans":"Porque un bisturí que solo corta hacia afuera no es instrumento, es arma: diseccionar el ideario del bando contrario lo hace cualquiera, y auditar el propio no lo hace casi nadie. La regla de pago lo vuelve procedimiento: un desenmascaramiento propio por cada uno ajeno, y el pago se hace con el ideario más parecido al propio, no con el más lejano, porque ahí es donde de verdad cuesta. La señal de que un dibujo ajeno salió mal es clara y se comprueba en un segundo: si el núcleo que dibujaste es un defecto que nadie de esa familia confesaría, dibujaste un muñeco, porque nadie pone un defecto en el centro de su propio ideario. Entonces la hoja se rehace con la mejor versión, como manda la regla del acero, que en este arco es la regla madre; y la crítica que venga después será más difícil y mucho más seria."}];
let ansVisible=false;
function genTask(){sfx('click');const type=document.getElementById('tgType').value;const count=parseInt(document.getElementById('tgCount').value);ansVisible=false;const out=document.getElementById('tgOut');out.innerHTML='';if(type==='identify')genIdentifyTask(out,count);else if(type==='classify')genClassifyTask(out,count);else if(type==='complete')genCompleteTask(out,count);else if(type==='explain')genExplainTask(out,count);fin('s-tareas');}
function _instrBlock(out,title,lines){const ib=document.createElement('div');ib.className='tg-instruction-block';ib.innerHTML=`<h4>📋 ${title}</h4>`+lines.map(l=>`<p>${l}</p>`).join('');out.appendChild(ib);}
function genIdentifyTask(out,count){_instrBlock(out,'Instrucción',['Copia en tu cuaderno; subraya, colorea o encierra el concepto técnico ilustrado en cada oración. Escribe al lado de qué concepto se trata.','<strong>Ejemplo:</strong> Su significado no queda cerrado nunca. → <span style="color:var(--jade);font-weight:700;">Concepto esencialmente disputado (Gallie, 1956)</span>']);_pick(identifyTaskDB,Math.min(count,identifyTaskDB.length)).forEach((item,i)=>{const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.s}</strong><div style="border-bottom:1.5px solid var(--border);min-width:220px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.type}</div></div>`;out.appendChild(div);});}
function genClassifyTask(out,count){_instrBlock(out,'Instrucción',['Copia la siguiente tabla en tu cuaderno. Para cada elemento, completa su tipo, características, ámbito y función.']);const items=_pick(classifyTaskDB,Math.min(count,classifyTaskDB.length));const wrap=document.createElement('div');wrap.style.overflowX='auto';const th=(t,extra='')=>`<th style="padding:0.3rem 0.4rem;border:1px solid var(--border);font-size:0.72rem;text-align:center;${extra}">${t}</th>`;let html=`<table style="width:100%;border-collapse:collapse;font-size:0.78rem;min-width:520px;"><thead><tr style="background:var(--pri-gl);">${th('Elemento','text-align:left;')}${th('Tipo')}${th('Características')}${th('Ámbito')}${th('Función')}</tr></thead><tbody>`;items.forEach(it=>{html+=`<tr><td style="padding:0.4rem 0.5rem;border:1px solid var(--border);font-weight:600;">${it.w}</td>`+Array(4).fill(`<td style="padding:0.4rem;border:1px solid var(--border);min-width:50px;"></td>`).join('')+'</tr>';});html+='</tbody></table>';wrap.innerHTML=html;out.appendChild(wrap);const ans=document.createElement('div');ans.className='tg-answer';ans.style.marginTop='0.8rem';ans.innerHTML='<strong>✅ Respuestas:</strong><br>'+items.map(it=>`<strong>${it.w}:</strong> Tipo: ${it.gen} | Características: ${it.n} | Ámbito: ${it.g} | Función: ${it.t}`).join('<br>');out.appendChild(ans);}
function genCompleteTask(out,count){_instrBlock(out,'Instrucción',['Copia y resuelve en tu cuaderno. Cada oración tiene un espacio ___. Elige y escribe la opción correcta.']);const pool=_shuffle([...completeTaskDB]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';const sent=item.s.replace('___','<span class="tg-blank" style="min-width:90px;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span>');div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${sent}</strong><div style="margin-top:0.4rem;font-size:0.82rem;color:var(--gray);">📝 Opciones: <strong>${item.opts.join(' | ')}</strong></div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function genExplainTask(out,count){_instrBlock(out,'Instrucción',['Copia las siguientes preguntas en tu cuaderno y responde cada una de forma clara y argumentada.']);const pool=_shuffle([...explainQuestions]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.q}</strong><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.3rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function toggleAns(){ansVisible=!ansVisible;document.querySelectorAll('.tg-answer').forEach(el=>el.style.display=ansVisible?'block':'none');sfx('click');}

