// ===================== LÍNEA DE TIEMPO INTERACTIVA =====================
const timelineData=[{"y":"1956","icon":"🔓","label":"Gallie nombra el problema","text":"<strong>W. B. Gallie</strong> publica <strong>«Essentially Contested Concepts»</strong>: hay conceptos cuyo significado <strong>no queda cerrado nunca</strong>. Y lo decisivo: <strong>eso no es un defecto del idioma, es su modo de existir</strong>. Etiqueta: clásico sólido de la filosofía."},{"y":"1958","icon":"✂️","label":"Berlin parte la libertad","text":"En Oxford, <strong>Isaiah Berlin</strong> dicta <strong>«Dos conceptos de libertad»</strong> y separa la <strong>negativa</strong> (que nadie me estorbe) de la <strong>positiva</strong> (poder de verdad hacer). Etiqueta: <strong>clásico sólido</strong>, y la fuente canónica del ejemplo central de esta etapa."},{"y":"El siglo","icon":"🚧","label":"La pelea de las dos","text":"<strong>Media pelea política del siglo cabe en cuál de las dos se está nombrando</strong>, y casi nunca se dice cuál. Los dos vecinos de la calle, los dos bloques de la guerra fría: la misma palabra pidiendo cosas contrarias, y cada lado acusando al otro de no tener ninguna."},{"y":"1996","icon":"🔬","label":"Freeden lo vuelve instrumento","text":"En <strong>«Ideologies and Political Theory»</strong>, <strong>Michael Freeden</strong> construye sobre los dos: una ideología es una <strong>morfología</strong>, un arreglo de conceptos. Etiqueta: <strong>académico sólido</strong>, la base del análisis morfológico de la materia entera."},{"y":"La anatomía","icon":"🎯","label":"Las tres capas","text":"<strong>Núcleo</strong> (lo que no se negocia sin dejar de ser eso), <strong>adyacentes</strong> (los que precisan el núcleo) y <strong>periféricos</strong> (lo que cambia con el lugar y la década). Con eso <strong>un ideario se dibuja en una página</strong>, y dos dibujos se pueden comparar."},{"y":"El movimiento","icon":"🔒","label":"La descontestación","text":"Toda ideología toma un concepto disputado, <strong>le fija un solo significado como si fuera el único posible</strong>, y <strong>vende ese cierre como sentido común</strong>. Aprender a ver ese gesto es aprender a leer política, y también a leerse."},{"y":"2003 y hoy","icon":"📐","label":"La rampa y el dibujo","text":"<strong>«Ideology: A Very Short Introduction»</strong> es la puerta corta y seria escrita por el <strong>propio dueño del instrumento</strong>. Y la práctica de esta etapa: <strong>tres textos que no se parezcan, una página cada uno</strong>, y uno de los tres de la propia casa."}];
function initTimeline(){const track=document.getElementById('timelineTrack');if(!track)return;timelineData.forEach((d,i)=>{const b=document.createElement('button');b.className='tl-node';b.type='button';b.dataset.idx=i;b.innerHTML=`<span class="tl-dot">${d.icon}</span><span class="tl-year">${d.y}</span><span class="tl-label">${d.label}</span>`;b.onclick=()=>showTimeline(i);track.appendChild(b);});}
function showTimeline(i){const d=timelineData[i];document.querySelectorAll('.tl-node').forEach(n=>n.classList.remove('tl-active'));document.querySelector(`.tl-node[data-idx="${i}"]`).classList.add('tl-active');document.getElementById('tlInfoIcon').textContent=d.icon;document.getElementById('tlInfoText').innerHTML=`<strong>${d.y} · ${d.label}.</strong> ${d.text}`;document.getElementById('tlInfo').style.display='flex';sfx('click');}

// ===================== SIMULACIÓN: MÉTODO DE POPPER =====================
let methodRunning=false;
function startMethod(){if(methodRunning)return;methodRunning=true;sfx('click');document.getElementById('methodBtn').style.display='none';document.getElementById('methodBranch').classList.remove('show');document.getElementById('methodResult').innerHTML='';const steps=['ms1','ms2','ms3','ms4'];const arrows=['ma1','ma2','ma3'];steps.forEach(s=>document.getElementById(s).classList.remove('active','done'));arrows.forEach(a=>document.getElementById(a).classList.remove('active'));let i=0;function next(){if(i>0){document.getElementById(steps[i-1]).classList.remove('active');document.getElementById(steps[i-1]).classList.add('done');}if(i<steps.length){if(i>0)document.getElementById(arrows[i-1]).classList.add('active');document.getElementById(steps[i]).classList.add('active');sfx('ok');i++;setTimeout(next,900);}else{document.getElementById('methodBranch').classList.add('show');}}next();}
function resolveMethod(declara){sfx(declara?'ok':'no');document.getElementById('methodBranch').classList.remove('show');document.getElementById('ms4').classList.remove('active');document.getElementById('ms4').classList.add('done');const r=document.getElementById('methodResult');if(declara){r.innerHTML='<div class="method-step done" style="opacity:1;"><span class="ms-num">5</span><span class="ms-icon">🎯</span><span class="ms-text"><strong>El cierre quedó declarado:</strong> el núcleo en prosa llana («todo niño puede aprender si alguien se sienta con él»), los adyacentes nombrados (acceso gratuito, temario oficial, lengua materna) y la periferia dicha como periferia (formato, aplicación, colores).</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">🤝</span><span class="ms-text"><strong>Y con eso la casa se volvió discutible:</strong> ahora alguien puede objetarle a M.E.T.A.S lo que M.E.T.A.S dijo, y no lo que imaginó que dijo. Declarar el cierre no debilita un ideario: lo vuelve auditable, y solo lo auditable se puede defender.</span></div>';}else{r.innerHTML='<div class="method-step done" style="opacity:1;border-color:var(--red);background:var(--red-gl);"><span class="ms-num">5</span><span class="ms-icon">🔒</span><span class="ms-text"><strong>Quedó una descontestación sin declarar:</strong> la frase fija por debajo un sentido de «libertad» y de «igualdad» y lo vende como sentido común. Suena a todo el mundo y no compromete a nadie.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">🪤</span><span class="ms-text"><strong>El costo llega el día del desacuerdo:</strong> cada lector le había puesto el significado que ya traía, y la casa no puede apelar a su propio texto porque su propio texto no decía nada. Se reescribe declarando el cierre.</span></div>';}methodRunning=false;document.getElementById('methodBtn').style.display='inline-flex';document.getElementById('methodBtn').textContent='🔄 Repetir simulación';sfx('fan');}

// ===================== LABORATORIO DE CONCEPTOS =====================
const parteData={"disputado":{"nombre":"El concepto disputado","icon":"🔓","estructura":{"title":"Qué es","info":"• De <strong>Gallie (1956)</strong>: concepto cuyo significado <strong>no se cierra nunca</strong><br>• Libertad, igualdad, justicia, democracia, mérito<br>• Y la clave: <strong>la disputa es su modo de existir</strong>, no un defecto"},"funcion":{"title":"Cómo se reconoce","info":"• Dos personas lo usan de acuerdo <strong>hasta el momento de aplicarlo</strong><br>• Nadie logra una definición que sirva a los dos lados<br>• Y sin embargo <strong>los dos lo usan correctamente</strong>"},"enfermedades":{"title":"Dónde se cae","info":"• Creer que se arregla <strong>definiendo mejor</strong>, de una vez y para siempre<br>• Tratarlo como un término descriptivo (kilómetro, fecha, peso)<br>• Acusar al otro de <strong>no saber castellano</strong> cuando usa el otro sentido"},"cuidados":{"title":"En esta casa","info":"• Ningún concepto disputado <strong>se usa sin decir en cuál de sus sentidos</strong><br>• Antes de discutir se pregunta cuál está pidiendo el otro<br>• Y se acepta que <strong>eso no acaba la pelea: la vuelve real</strong>"}},"libertad":{"nombre":"Las dos libertades","icon":"✂️","estructura":{"title":"Qué es","info":"• De <strong>Berlin (1958)</strong>, en Oxford: el ejemplo mayor partido en dos<br>• <strong>Negativa:</strong> que nadie me estorbe<br>• <strong>Positiva:</strong> poder de verdad hacer"},"funcion":{"title":"Cómo se reconoce","info":"• La negativa <strong>se guarda estándose quieto</strong>: basta que nadie intervenga<br>• La positiva <strong>no se alcanza sin que alguien mueva algo</strong><br>• Prueba rápida: ¿esto pide que quiten algo o que pongan algo?"},"enfermedades":{"title":"Dónde se cae","info":"• Decir «libertad» y no decir cuál: <strong>ahí vive la trampa</strong><br>• Regalar una libertad <strong>sin preguntar cuál quería el otro</strong><br>• Acusar al rival de estar contra la libertad <strong>cuando está contra la tuya</strong>"},"cuidados":{"title":"En esta casa","info":"• Toda petición se traduce: <strong>¿quitar un estorbo o dar un medio?</strong><br>• Las dos son libertad, y las dos tienen coste<br>• Y el coste <strong>se dice en la misma frase</strong>, no en la letra chica"}},"morfologia":{"nombre":"La morfología","icon":"🎯","estructura":{"title":"Qué es","info":"• De <strong>Freeden (1996)</strong>: un ideario es un <strong>arreglo de conceptos</strong><br>• Tres capas: <strong>núcleo</strong>, <strong>adyacentes</strong>, <strong>periféricos</strong><br>• Y por eso <strong>se puede dibujar en una página</strong>"},"funcion":{"title":"Cómo se reconoce","info":"• El <strong>núcleo</strong> se encuentra quitándolo: si sigue siendo eso, no era<br>• Los <strong>adyacentes</strong> le dan forma concreta: sin ellos no decide nada<br>• Los <strong>periféricos</strong> cambian con el lugar y la década"},"enfermedades":{"title":"Dónde se cae","info":"• Leer el ideario como <strong>lista de opiniones</strong> al mismo nivel<br>• Poner de núcleo <strong>el punto 1</strong>, que suele ser el más presentable<br>• Pelear la periferia <strong>como si fuera el núcleo</strong>"},"cuidados":{"title":"En esta casa","info":"• Todo ideario se dibuja <strong>antes</strong> de opinar, y en una sola página<br>• Uno de los tres dibujos <strong>es de esta casa</strong><br>• Y si el núcleo ajeno <strong>no lo firmaría nadie de esa familia, se rehace</strong>"}},"descontesta":{"nombre":"La descontestación","icon":"🔒","estructura":{"title":"Qué es","info":"• El movimiento clave de Freeden: <strong>fijar un solo significado</strong><br>• A un concepto que estaba abierto, <strong>como si fuera el único posible</strong><br>• Y vender ese cierre <strong>como sentido común</strong>"},"funcion":{"title":"Cómo se reconoce","info":"• El texto usa el concepto <strong>sin decir en qué sentido</strong><br>• Y no menciona que hubo alternativa: <strong>la borra</strong><br>• <strong>Prueba de tres segundos:</strong> pon el otro sentido en la misma frase"},"enfermedades":{"title":"Dónde se cae","info":"• Creer que solo descontestan <strong>los idearios ajenos</strong><br>• Confundir descontestar con <strong>definir con claridad</strong>: definir declara, descontestar esconde<br>• Dejar la propia descontestación <strong>sin declarar por comodidad</strong>"},"cuidados":{"title":"En esta casa","info":"• Cuando la casa cierra un concepto, <strong>lo dice y firma el cierre</strong><br>• Cada cierre ajeno detectado <strong>se paga con uno propio</strong><br>• Y el pago se hace con <strong>el ideario más parecido, no con el más lejano</strong>"}}};
let labParte='disputado',labAspecto='estructura';
function labShowParte(parteKey){labParte=parteKey;updateLabDisplay();document.querySelectorAll('.lab-cont-btn').forEach(b=>b.classList.remove('active-pri'));const btn=document.querySelector(`[data-parte="${parteKey}"]`);if(btn)btn.classList.add('active-pri');if(typeof sfx==='function')sfx('click');}
function labShowAspecto(aspectoKey){labAspecto=aspectoKey;updateLabDisplay();document.querySelectorAll('.lab-asp-btn').forEach(b=>b.classList.remove('active-sec'));const btn=document.querySelector(`[data-aspecto="${aspectoKey}"]`);if(btn)btn.classList.add('active-sec');if(typeof sfx==='function')sfx('click');}
function updateLabDisplay(){const data=parteData[labParte];const asp=data[labAspecto];document.getElementById('lab-sentence').innerHTML=`🦉 Explorando: <strong>${data.nombre}</strong> → <strong>${asp.title}</strong>`;document.getElementById('lab-display').innerHTML=`<div class="lab-cont-header">${data.icon} ${data.nombre}</div><div class="lab-asp-title">${asp.title}</div><div class="lab-asp-info">${asp.info}</div>`;}

// ===================== PREGUNTAS DE LAS LECTURAS =====================
// Tres baterías sobre los SEIS textos (norma 5-nonies): comprensión lectora
// (30), completar (12) y análisis complejo (12), repartidas en 5, 2 y 2 por
// voz: Borges, Cervantes, Harari, Entrevista, Quintero y Gala, y Debate.
//
// La etiqueta «t» manda, y por eso hay que cuidarla más que los enunciados:
// js/lecturas.js filtra por ella para meter las preguntas DENTRO de su
// lectura, así que una etiqueta suelta («las cinco», «todas») deja esa
// pregunta fuera de las seis tarjetas y nadie la vuelve a ver. Por lo mismo
// cada pregunta se contesta con SU texto delante y no con otro: antes había
// preguntas de completar que se respondían con tres lecturas distintas, y
// eso servía cuando la batería vivía suelta al final de la sección.
//
// Y los enunciados de análisis van sin el número de cabeza: era el número
// del banco global de diez, y con dos por lectura mentiría.
const lectComprensionBank=[{"t":"Borges","q":"¿Qué tarea le encomendaron al narrador en el diccionario?","o":["a) Corregir las tildes de la letra L","b) Redactar en veinte líneas la definición de «libertad»","c) Escribir el prefacio de la obra","d) Traducir el diccionario al inglés"],"c":1},{"t":"Borges","q":"¿Por qué no le servía ninguna de sus catorce versiones?","o":["a) Porque el director las rechazaba sin leerlas","b) Porque al cerrar la definición por un lado se le abría por otro","c) Porque le faltaban ejemplos","d) Porque eran demasiado largas"],"c":1},{"t":"Borges","q":"¿Qué confesó Samuel Johnson en el prefacio de su diccionario de 1755?","o":["a) Que había copiado de otros diccionarios","b) Que había empezado creyendo que podía fijar el idioma y terminó sabiendo que era vano","c) Que la obra le había costado poco trabajo","d) Que solo había definido las palabras difíciles"],"c":1},{"t":"Borges","q":"¿Cómo terminó el narrador su encargo?","o":["a) Renunciando al empleo","b) Copiando la definición de Johnson","c) Entregando una sola definición muy larga","d) Entregando dos definiciones numeradas, con una nota"],"c":3},{"t":"Borges","q":"Según el final del cuento, ¿qué eran aquellos números que el director despachó como tipografía?","o":["a) Un error de imprenta","b) Una costumbre inútil de los diccionarios","c) La primera página de una morfología","d) Una idea de Johnson"],"c":2},{"t":"Cervantes","q":"¿Qué entendía por libertad el hidalgo del capítulo?","o":["a) Poder sacar agua del pozo","b) Que nadie le entrase en su dehesa ni le pusiera tributo","c) Que el concejo le diera cabras","d) Que todos fueran iguales"],"c":1},{"t":"Cervantes","q":"¿Y qué entendía por libertad el labrador?","o":["a) Poder sacar agua del único pozo de la comarca","b) Que nadie le hablara","c) Que le quitaran el tributo","d) Tener más cabras que el hidalgo"],"c":0},{"t":"Cervantes","q":"¿Qué episodio propio recuerda don Quijote para probar su sentencia?","o":["a) Que dio libertad a unos hombres en cadenas y le pagaron con pedradas","b) La aventura de los molinos","c) La bacía del barbero","d) La cueva de Montesinos"],"c":0},{"t":"Cervantes","q":"¿Qué mandó dibujar don Quijote en el suelo?","o":["a) Un mapa de la comarca","b) Tres cercos, uno dentro de otro","c) El plano del pozo","d) Dos rayas paralelas"],"c":1},{"t":"Cervantes","q":"¿Qué le quiso vender Sancho al labrador?","o":["a) Dos pares de antojos de Toledo","b) Su libertad de dormir a mediodía","c) El cántaro de vino","d) La bacía de su amo"],"c":1},{"t":"Harari","q":"Según el ensayo, ¿qué tipo de ficciones funcionan mejor para unir a millones?","o":["a) Las que no están del todo definidas","b) Las que están definidas con precisión","c) Las que se escriben en varios idiomas","d) Las que tienen un autor famoso"],"c":0},{"t":"Harari","q":"¿Cuál fue el resultado de la votación de la Declaración Universal de Derechos Humanos, el 10 de diciembre de 1948?","o":["a) Cuarenta y ocho a favor, ninguno en contra y ocho abstenciones","b) Cuarenta países a favor y diez en contra","c) Aprobación por unanimidad absoluta","d) Veinte a favor y veinte en contra"],"c":0},{"t":"Harari","q":"¿Cómo explica el ensayo que en 1948 nadie votara en contra?","o":["a) Porque el mundo estaba de acuerdo","b) Porque no se permitía votar en contra","c) Porque el texto era muy corto","d) Porque la palabra estaba abierta y cada bloque leyó adentro su propio programa"],"c":3},{"t":"Harari","q":"Según el ensayo, ¿dónde suele estar el núcleo de un ideario?","o":["a) En el punto número uno","b) En el último punto","c) En uno de los del medio, el que dice cómo se resuelve un desacuerdo","d) En el título"],"c":2},{"t":"Harari","q":"¿Cuál es el uso del instrumento que, dice el ensayo, casi nadie hace?","o":["a) Dibujar los tres anillos de su propia casa","b) Aplicarlo a los partidos políticos","c) Aplicarlo a las empresas","d) Aplicarlo a los documentos históricos"],"c":0},{"t":"Entrevista","q":"Según Freeden en la entrevista, ¿qué es una ideología?","o":["a) Una mentira organizada","b) Una lista de opiniones","c) Un partido político","d) Una morfología: un arreglo de conceptos con núcleo, adyacentes y periferia"],"c":3},{"t":"Entrevista","q":"¿Por qué dice Freeden que el libro de 2003 le costó más que el de 1996?","o":["a) Porque era mucho más largo","b) Porque lo escribió en otro idioma","c) Porque nadie quería publicarlo","d) Porque tuvo que decidir qué era núcleo y qué era periferia de su propio libro"],"c":3},{"t":"Entrevista","q":"¿Qué diferencia señala Freeden entre declarar un cierre y esconderlo?","o":["a) Ninguna: los dos son iguales","b) El declarado es siempre falso","c) El escondido se discute mejor","d) Un cierre declarado se puede discutir; uno escondido se hereda"],"c":3},{"t":"Entrevista","q":"¿Qué le recomienda Freeden a una familia que va a escribir su credo?","o":["a) Dibujar tres anillos en media hoja antes de redactar una sola frase","b) Copiar el credo de otra familia","c) Empezar redactando el punto número uno","d) No escribir nada y confiar en la costumbre"],"c":0},{"t":"Entrevista","q":"¿Qué resultado adelanta Freeden de haberse dibujado a sí mismo?","o":["a) Que su núcleo salió enorme","b) Que no encontró periferia","c) Que el plano resultó imposible","d) Que el núcleo sale más pequeño de lo esperado y la periferia, enorme"],"c":3},{"t":"Quintero y Gala","q":"¿Qué pone Gala en el anillo del centro de su propia morfología?","o":["a) Que la belleza no es un lujo sino un derecho","b) El teatro y su columna","c) Los premios y las fotos","d) La memoria de al-Ándalus"],"c":0},{"t":"Quintero y Gala","q":"Según Gala, ¿de qué se muere una palabra?","o":["a) De que la discutan demasiado","b) De que la usen los poetas","c) De éxito: cuando ya nadie pregunta qué quiere decir","d) De vieja: todas se mueren con su siglo"],"c":2},{"t":"Quintero y Gala","q":"¿Con qué compara Gala la votación de 1948?","o":["a) Con una subasta","b) Con un pleito de vecinos","c) Con las cartas de amor, que las firma todo el mundo y cada uno entiende la suya","d) Con una corrida de toros"],"c":2},{"t":"Quintero y Gala","q":"¿Qué cierre confiesa Gala haber vendido?","o":["a) En «El manuscrito carmesí» prestó su voz a Boabdil y eligió qué significaba «pérdida»","b) El de la palabra «libertad» en su columna","c) Ninguno: dice que la literatura no descontesta","d) El de la palabra «éxito» en sus memorias"],"c":0},{"t":"Quintero y Gala","q":"Para Gala, en el cierre de la conversación, ¿quién es libre?","o":["a) El que usa las palabras más grandes","b) El que nunca firma nada","c) El que se atreve a decir en qué sentido dice las palabras grandes","d) El que tiene la puerta abierta"],"c":2},{"t":"Debate","q":"Según el careo, ¿dónde y cuándo publicó Gerald C. MacCallum el artículo que sostiene la postura B?","o":["a) En 1958, en una lección inaugural en Oxford","b) En 1967, en la revista «The Philosophical Review»","c) En 1996, en «Ideologies and Political Theory»","d) En 1956, en los «Proceedings of the Aristotelian Society»"],"c":1},{"t":"Debate","q":"¿Qué forma dice la postura B que tiene toda afirmación inteligible sobre la libertad?","o":["a) Libertad negativa frente a libertad positiva","b) Núcleo, adyacentes y periferia","c) x está libre de y para hacer (o no hacer, o llegar a ser) z","d) Concepto disputado frente a concepto cerrado"],"c":2},{"t":"Debate","q":"¿Con qué argumento contesta la defensa a la fórmula de los tres términos, apoyándose en la introducción de 1969 a «Four Essays on Liberty»?","o":["a) Que la fórmula fue publicada demasiado tarde para ser tomada en serio","b) Que los tres términos no se pueden escribir en media hoja","c) Que el esquema de tres términos es un invento de la literatura posterior a Berlin","d) Que quien lucha contra sus cadenas no tiene por qué proponerse ningún estado ulterior definido"],"c":3},{"t":"Debate","q":"¿Qué caso de 1905 usa la objeción para preguntar si la libertad negativa tiene también su genealogía de abusos?","o":["a) La votación de la Declaración Universal de Derechos Humanos","b) «Lochner contra Nueva York», donde se anuló una ley que limitaba a sesenta horas la semana de los panaderos","c) La publicación del diccionario de Samuel Johnson","d) El pleito de los dos vecinos por los topes de la calle"],"c":1},{"t":"Debate","q":"Según la moderación, ¿qué prueba casera decidiría la disputa a favor de la postura A?","o":["a) Que la mayoría de la gente prefiera la palabra «negativa»","b) Que la fórmula de los tres términos sea más corta de escribir","c) Que dos partes llenen igual las tres casillas y aun así sigan enfrentadas, porque una pregunta quién manda y la otra hasta dónde le estorban","d) Que ningún autor posterior a 1967 vuelva a usar la dicotomía"],"c":2}];
const lectCompletarBank=[{"t":"Borges","q":"Samuel Johnson publicó su diccionario de la lengua inglesa en ___.","a":"1755"},{"t":"Borges","q":"El narrador llegó a tener ___ versiones de la definición y ninguna le servía.","a":"catorce"},{"t":"Cervantes","q":"El labrador quería poder sacar agua del ___ del hidalgo.","a":"pozo"},{"t":"Cervantes","q":"Don Quijote los hizo dibujar tres ___ en el suelo, uno dentro de otro.","a":"cercos"},{"t":"Harari","q":"El artículo primero de la Declaración francesa de ___ dice que los hombres nacen y permanecen libres e iguales en derechos.","a":"1789"},{"t":"Harari","q":"El ensayo recuerda que la Declaración de Independencia de los Estados Unidos, de ___, había hablado de la vida, la libertad y la búsqueda de la felicidad.","a":"1776"},{"t":"Entrevista","q":"La entrevista presenta a Freeden en un oficio raro: leer idearios sin ___ con ellos.","a":"pelearse"},{"t":"Entrevista","q":"Freeden no le pide a nadie que no cierre un concepto: le pide que ___ su cierre.","a":"firme"},{"t":"Quintero y Gala","q":"Antonio Gala cuenta que estrenó «Anillos para una dama» en ___.","a":"1973"},{"t":"Quintero y Gala","q":"Gala abrió en Córdoba, en ___, su Fundación para jóvenes creadores.","a":"2002"},{"t":"Debate","q":"Gerald C. MacCallum publicó «Negative and Positive Freedom» en ___.","a":"1967"},{"t":"Debate","q":"Para la postura B, la libertad es siempre una relación de tres términos, es decir una relación ___.","a":"triádica"}];
const lectAnalisisBank=[{"t":"Borges","q":"El narrador dice que comprendió su fracaso «con una mezcla de humillación y de alivio». Explica de dónde sale cada una de las dos cosas y por qué el alivio es el hallazgo de esta etapa.","guia":"La humillación es la del oficio: un mes de trabajo, catorce versiones y ninguna sirve, y mientras tanto el narrador cree que le falta talento o paciencia. El alivio llega cuando descubre que el fracaso no era suyo sino de la tarea, y llega con nombre y fecha: Gallie sostuvo en 1956 que hay conceptos cuyo significado no queda cerrado nunca y que esa apertura no es un defecto que la filosofía deba remediar, sino su manera de existir. Se valora que la respuesta note el orden de las dos piezas, porque ahí está la lección: primero se intenta cerrar y se falla, y solo después se entiende que la palabra era de las que no se cierran. Y se valora sobre todo que vea por qué el alivio no es resignación: si cerrar un concepto disputado es imposible de una vez y para todos, entonces cada cierre concreto es un acto de alguien, y un acto se puede fechar, atribuir y discutir. Ahí empieza el instrumento que la etapa entrega. Una respuesta que se quede en «el narrador se consoló» no ha leído el párrafo de Gallie."},{"t":"Borges","q":"El director despachó las dos definiciones numeradas como «tipografía», y el narrador dice que tenía razón y que a la vez no la tenía del todo. Explica las dos mitades de ese juicio.","guia":"Tenía razón en lo primero: los diccionarios llevan siglos numerando los sentidos de una palabra, la solución es vieja, funciona y resuelve el pleito más tonto, que es el de quién habla bien el idioma. Numerar separa, y separar ya es mucho. No la tenía del todo porque numerar deja los sentidos sueltos, uno al lado del otro, sin decir cuál sostiene a cuál ni qué pasa cuando alguien elige uno y calla el otro. Eso es lo que el narrador encuentra muchos años después en Freeden (1996): si el concepto no se puede cerrar, entonces cerrarlo es un acto, y ese acto tiene estructura, un núcleo que no se negocia, unos conceptos adyacentes que lo precisan y una periferia que cambia con la década. Se valora que la respuesta lea la última frase del cuento como lo que es, la bisagra entre las dos mitades: aquellos números eran la primera página de una morfología, es decir el paso uno de dos. Y se valora que no se convierta al director en el tonto de la historia: su encogimiento de hombros es correcto y es insuficiente, que son cosas distintas."},{"t":"Cervantes","q":"Don Quijote dice que «quien regala una libertad sin preguntar cuál, hace merced a su propio gusto y no al del prójimo». Traduce esa frase al vocabulario de esta etapa y da un ejemplo de la vida real.","guia":"Traducida: quien actúa sobre un concepto disputado sin declarar en cuál de sus sentidos lo está usando, descontesta por su cuenta y le impone al otro su cierre, aunque crea estar ayudando. El propio don Quijote es el ejemplo mayor y por eso la frase le duele: liberó a los galeotes quitándoles el estorbo (libertad negativa) cuando ellos querían otra cosa, y se lo pagaron a pedradas. Un ejemplo de la vida real vale cualquiera que tenga las dos piezas, el bien intencionado y el cierre no declarado: la beca que se da como dinero cuando lo que faltaba era transporte, la regla del hogar que se levanta «para que sean libres» cuando lo que hacía falta era acompañamiento, la donación de equipo a una escuela que no tiene electricidad. La corrección es siempre la misma pregunta, y es de una línea: cuál de las dos libertades está pidiendo el otro."},{"t":"Cervantes","q":"¿Por qué el capítulo termina con «el que dibuja el cerco del vecino y nunca el suyo, no tiene bisturí, tiene lanza»? Relaciona esa frase con la regla de pago de la casa.","guia":"Porque el instrumento y el arma se distinguen por la dirección en que se usan, no por su forma. Diseccionar el ideario ajeno produce ventaja en la discusión y no cuesta nada; diseccionar el propio produce hallazgos incómodos y no da ninguna ventaja inmediata, así que casi nadie lo hace sin obligación. La frase pone la prueba en el gesto y no en la intención: no pregunta si quien corta es honesto, pregunta cuántos cercos propios ha dibujado. La regla de pago de la casa es esa misma exigencia convertida en procedimiento contable, un desenmascaramiento propio por cada uno ajeno, y con un detalle que la hace difícil: el pago se hace con el ideario más parecido al propio, no con el más lejano, porque con el lejano se cumple la apariencia y no el propósito."},{"t":"Harari","q":"El ensayo afirma que la imprecisión de las grandes declaraciones «no fue un descuido de redactores apurados». Defiende esa tesis con el dato de 1948 y explica su lado incómodo.","guia":"La tesis se defiende con la votación: el 10 de diciembre de 1948, cuarenta y ocho países votaron a favor de la Declaración Universal, ninguno en contra y ocho se abstuvieron, y eso ocurrió con el mundo partiéndose en dos bloques que iban a amenazarse durante cuarenta años. Un texto que hubiera especificado qué libertad y qué igualdad no habría reunido esa mayoría: la apertura del concepto fue la condición del acuerdo, no un defecto de redacción. El lado incómodo es el que sigue: un acuerdo así no es un acuerdo sobre lo que las palabras dicen, sino sobre las palabras, y por eso los dos bloques pudieron pasar cuarenta años acusándose de violar el mismo documento que ambos habían firmado. Sirve para empezar y no alcanza para decidir; el trabajo de decidir aparece después, y es el que el bisturí hace."},{"t":"Harari","q":"El ensayo dice que el núcleo «no es el punto número uno, sino uno de los del medio, el que dice cómo se resuelve un desacuerdo». Explica por qué es ahí, y qué consecuencia práctica tiene al leer la declaración de principios de una organización.","guia":"Es ahí porque el punto que fija cómo se resuelve un desacuerdo gobierna a todos los demás: de él depende qué pasa cuando dos principios chocan, y ningún principio significa nada operativo hasta que se sabe quién decide en el choque. Los puntos de apertura, en cambio, suelen elegirse por presentables, para que nadie objete, y por tanto suelen ser los más vagos y los más fáciles de firmar. La consecuencia práctica es que la lectura no se hace en el orden impreso: se busca directamente el punto del procedimiento (quién decide, con qué mayoría, quién puede vetar, qué pasa si no hay acuerdo) y desde ahí se leen los otros. Y si ese punto no existe en el documento, el hallazgo es igual de importante: la organización tiene el núcleo fuera del papel, en quien manda de hecho."},{"t":"Entrevista","q":"Freeden sostiene que la descontestación la hace toda ideología «sin excepción», y pone dos ejemplos: el liberalismo con la libertad y el socialismo con la igualdad. Explica los dos cierres y por qué dice que no lo cuenta como acusación.","guia":"Los dos cierres se cuentan con lo que la entrevista dice: el liberalismo toma la libertad y la fija como no interferencia, o bien como autonomía, y deja de mencionar el otro sentido; el socialismo toma la igualdad y la lleva más allá de la igualdad ante la ley, hasta las condiciones materiales, y presenta ese cierre como lo obvio. Lo que se valora es que la respuesta explique el «sin excepción» con el argumento que él mismo da, y no con buena voluntad: un concepto abierto no decide nada, y para decidir hay que cerrarlo, de modo que cerrar no es el pecado de una ideología sino su oficio. La acusación, si la hay, no cae sobre el cierre: cae sobre el cierre escondido, porque uno declarado se puede discutir y uno escondido se hereda. Se valora también que la respuesta no se quede en el aire y diga qué cambia al leer: en vez de discutir punto por punto con un ideario, se busca qué concepto grande cerró, en qué sentido lo cerró y si lo dijo. Y una respuesta completa acepta la incomodidad de que la regla vale también para la casa que la enseña."},{"t":"Entrevista","q":"Freeden propone una prueba casera «de las que caben en un viaje de autobús». Explica en qué consiste, por qué funciona, y aplícala a una frase que se diga de verdad en tu casa o en tu escuela.","guia":"La prueba es esta: se toma la frase que suena obvia y se le pone el otro significado del concepto, sin tocar nada más; si la frase se vuelve absurda o cambia de bando, había un cierre escondido. Funciona porque un concepto que de verdad estuviera abierto aguantaría los dos sentidos sin romperse, y el que se rompe delata que alguien ya había elegido uno y no lo dijo. Es barata a propósito: tres segundos de trabajo que ahorran años de discutir con un texto que nunca dijo nada. Se valora que la aplicación sea real y no de manual, con la frase escrita tal como se dice («aquí cada quien es libre de estudiar lo que quiera», «en esta escuela se premia el mérito»), el otro sentido puesto encima y el resultado descrito con honradez, incluida la posibilidad de que la frase aguante y no hubiera cierre escondido. Y se valora que la respuesta note el límite de la prueba: detecta el cierre, no dice si el cierre estaba bien."},{"t":"Quintero y Gala","q":"Gala dice: «Las palabras grandes son andaluzas, Jesús: hospitalarias, abren la casa entera, y uno no sabe si es huésped o prisionero hasta que intenta salir». Explica qué parte del temario de la etapa está diciendo con esa imagen.","guia":"La hospitalidad de la imagen es la apertura del concepto: como no está cerrado, cabe dentro mucha gente que quiere cosas distintas, y por eso las palabras grandes reúnen firmas y multitudes. La prisión aparece después, y solo cuando uno intenta usar la palabra en un sentido distinto del que otro ya le había fijado: ahí descubre que la casa tenía dueño y que el cierre estaba puesto sin avisar. Eso es la descontestación contada sin la palabra técnica. Se valora que la respuesta enlace la imagen con lo que Gala cuenta de sí mismo unas líneas antes, que a él lo encerraron las palabras «poeta» y «éxito» y que casi siempre fue con su consentimiento, porque ese detalle es el que convierte la imagen en aviso práctico: los cierres que más aprietan son los que uno acepta sin discutir. Y se valora que no se lea como queja contra las palabras abiertas: el propio Gala dice que lo triste no son las palabras disputadas sino las muertas, aquellas en las que ya todos estamos de acuerdo porque ya no nos importan."},{"t":"Quintero y Gala","q":"Gala responde que «el dinero es el descontestador más fino que existe, porque no discute: compra el diccionario entero y le cambia una página sin avisar». Explica el mecanismo que describe y da un caso donde se pueda ver.","guia":"El mecanismo tiene tres pasos y conviene decirlos separados. Primero, quien paga no argumenta ni pide permiso: fija el significado de una palabra grande donde esa palabra se usa (el reglamento, el anuncio, la convocatoria, el formulario). Segundo, ese sentido queda circulando ya cerrado, sin la marca de quién lo cerró ni cuándo. Tercero, los demás lo heredan creyendo que es sentido común, que es justo lo que hace fino al procedimiento: no se ve el acto, solo el resultado. Gala pone al lado su propia consecuencia, y es la que le quita el sueño: al que no sabe dónde está el núcleo de lo que firma se lo descontestan otros, y encima le cobran la firma. Se valora un caso concreto y comprobable, con la palabra nombrada y el pagador nombrado, del tipo «mérito» en las bases de una beca, «calidad» en un pliego de compras o «excelencia» en la publicidad de una academia. Y se valora que la respuesta recoja la defensa que el propio texto propone, que es de una línea: mirar quién firma la definición antes de firmar uno debajo."},{"t":"Debate","q":"La objeción sostiene que su esquema de tres casillas abarca todo lo que se ha dicho sobre la libertad, y la defensa contesta que un molde donde cabe todo no distingue nada. ¿Es decisiva esa objeción? Argumenta usando la diferencia entre describir y decidir.","guia":"No es decisiva por sí sola, y explicar por qué es el ejercicio. Un esquema descriptivo se juzga por si permite escribir cualquier caso sin deformarlo, y ahí abarcar es una virtud y no un defecto: la fórmula de MacCallum obliga a nombrar sujeto, estorbo y fin, y eso desarma lemas que parecían decir algo. Una distinción clasificatoria, en cambio, se juzga por lo que separa, y ahí la objeción de la defensa muerde: si todo entra en el molde, el molde no reparte el terreno. Las dos cosas son verdaderas porque las dos herramientas hacen trabajos distintos, y confundirlas es el error de fondo de la pelea. La respuesta buena señala además el punto donde la objeción sí pega de verdad: cuando para meter un caso en el esquema hay que inventarle una casilla que el hablante nunca puso, como el fin que se le atribuye a quien solo quiere que le quiten las cadenas. Ahí el esquema dejó de describir y empezó a corregir, y esa es la única versión de la objeción que resiste. Y se valora que la respuesta recoja la contestación de la objeción, que es corta y buena: la casilla del fin puede quedar abierta (libre para hacer o ser lo que elija), y el propio Berlin llena una casilla de ese tipo cuando dice que la libertad de la que habla es la oportunidad de obrar. Con eso, el asalto queda en tablas y no ganado, que es como lo anota el careo."},{"t":"Debate","q":"Si la postura B tuviera razón, ¿qué habría que cambiar en la hoja del bisturí de esta etapa y en la manera de contar el caso de los dos vecinos? ¿Y qué habría que añadir si la razón fuera de la postura A?","guia":"Si gana B, el renglón que pregunta cuál de las dos libertades se está nombrando sale de la hoja y se queda solo el de las tres casillas: quién es el sujeto, de qué está libre y para hacer qué. El caso de los dos vecinos se contaría sin etiquetas: no son dos conceptos, es el mismo concepto con distinto sujeto (los hijos frente al conductor) y distinto estorbo (los carros veloces frente al reglamento), y el hallazgo se vuelve más incómodo y más útil, porque obliga a discutir quién cuenta como sujeto en vez de repartir bandos. Si gana A, no se quita nada: se conserva el segundo renglón, el que pregunta cuál de las dos preguntas está contestando el texto, la de quién manda o la de hasta dónde le estorban a uno. La respuesta completa nota lo que la casa hace hoy, que es llevar los dos renglones a la par mientras la disputa siga abierta, y que el orden en que están escritos es comodidad de escritura y no veredicto, cosa que el propio careo declara en su último párrafo. Se valora especialmente que la respuesta vea que las dos opciones son acumulables y que lo único innegociable es declarar cuál se está usando en cada análisis, que es exactamente lo que esta etapa le exige a cualquier otro ideario."}];
/* Las tres baterías de pantalla las monta ahora js/lecturas.js dentro de
   cada lectura, leyendo estos mismos bancos por su etiqueta de voz. */

/* ---------- impresión: cada lectura por separado ---------- */
// La etiqueta del estatus viaja SIEMPRE con el texto impreso: una hoja
// suelta con un pastiche sin declarar es exactamente la fuente inflada que
// el Estudio Mayor enseña a cazar.
const LECTURAS_IMPR={
  borges:{titulo:'La palabra que no se deja cerrar',tipo:'Cuento, a la manera de Jorge Luis Borges'},
  cervantes:{titulo:'De la libertad que pedían dos, siendo dos libertades',tipo:'Capítulo, a la manera de Miguel de Cervantes Saavedra'},
  harari:{titulo:'La palabra que firmaron todos',tipo:'Ensayo, a la manera de Yuval Noah Harari'},
  entrevista:{titulo:'El cartógrafo de las ideologías',tipo:'Entrevista imaginada con Michael Freeden, a la manera de Juan Cruz',
    etiq:'<strong>⚠️ Ejercicio de estilo de la casa, en homenaje.</strong> Esta entrevista es <strong>imaginada</strong> y <strong>el encuentro nunca ocurrió</strong>: Michael Freeden (nacido en 1944) y Juan Cruz (Puerto de la Cruz, Tenerife, 1948) son personas reales y vivas, toda obra, fecha y cifra citada es real y comprobable, y lo único inventado es la conversación, que escribió el Proyecto Educativo F.A.R.O. imitando sus voces.'},
  gala:{titulo:'La palabra abierta',tipo:'El Loco de la Colina: Jesús Quintero conversa con Antonio Gala (conversación imaginada)',
    etiq:'<strong>⚠️ Ejercicio de estilo de la casa, en homenaje.</strong> Esta conversación es <strong>imaginada</strong> y <strong>nunca ocurrió</strong>: Jesús Quintero (1940-2022) y Antonio Gala (1930-2023) son personas reales que sí se entrevistaron varias veces; sus voces se imitan aquí en homenaje, y toda obra, fecha y cifra citada dentro es real y comprobable.'},
  // El careo va aquí con las otras cinco porque el pliego de «las seis» las
  // recorre por esta tabla: sin su entrada, la sexta hoja no salía. Y su
  // etiqueta se escribe AQUÍ, no se hereda: el careo no imita a nadie, así
  // que la del pastiche («NO es obra de ese autor») sería mentira en su
  // hoja. Dejársela a FaroLecturas.etiquetaCareo() obligaba a fabricar
  // primero esa mentira y confiar en que llegara el reemplazo, y el
  // reemplazo se salta si el cuerpo ya dice «Careo escrito por la casa»:
  // bastaba con retocar esa frase en la nota de pantalla para que la hoja
  // saliera declarándose pastiche y nada avisaba. Escrita aquí, la hoja
  // sale bien aunque el aparato compartido falle o llegue tarde.
  debate:{titulo:'¿Una libertad o dos?',tipo:'Careo: las dos posturas de una disputa abierta, con sus réplicas',
    etiq:'<strong>⚖️ Careo escrito por la casa sobre una disputa real.</strong> Los turnos los firman los <strong>papeles</strong> (moderación, defensa, objeción) y no personas: aquí no se le pone a nadie una palabra en la boca. Los investigadores se citan en tercera persona como fuentes, <strong>toda obra, revista, fecha y cifra es real y comprobable</strong>, y cada postura va escrita en su mejor versión, no en la que sería fácil de tumbar.'},
};
function _hojaImpresa(titulo,cuerpo,pieExtra){
  return `<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>${titulo} · El bisturí de Freeden · F.A.R.O.</title><style>
@page{size:letter;margin:16mm 15mm;}
*{margin:0;padding:0;box-sizing:border-box;}
body{font-family:Georgia,'Times New Roman',serif;font-size:11.5pt;line-height:1.55;color:#111;background:#fff;}
h1{font-family:Arial,Helvetica,sans-serif;font-size:15pt;color:#0b4f4a;margin-bottom:2mm;line-height:1.2;}
.tipo{font-family:Arial,Helvetica,sans-serif;font-size:9.5pt;color:#555;margin-bottom:3mm;}
.ruta{font-family:Arial,Helvetica,sans-serif;font-size:9pt;color:#0f766e;border-bottom:1.5pt solid #0f766e;padding-bottom:1.5mm;margin-bottom:3mm;display:flex;justify-content:space-between;gap:6mm;}
.etiqueta{border:1.2pt solid #0f766e;background:#f0fdfa;border-radius:2mm;padding:2.5mm 3mm;font-family:Arial,Helvetica,sans-serif;font-size:9pt;line-height:1.4;margin-bottom:4mm;}
.idline{font-family:Arial,Helvetica,sans-serif;font-size:9pt;display:flex;gap:4mm;margin-bottom:3mm;}
.idline span.r{flex:1;border-bottom:0.8pt solid #666;}
p.t{text-align:justify;margin-bottom:2.6mm;text-indent:6mm;}
p.t:first-of-type{text-indent:0;}
h2{font-family:Arial,Helvetica,sans-serif;font-size:11pt;color:#0b4f4a;margin:4mm 0 2mm;}
.sec{font-family:Arial,Helvetica,sans-serif;font-size:10.5pt;font-weight:700;color:#0f766e;background:#f0fdfa;border-left:3pt solid #0f766e;padding:1.2mm 2.5mm;margin:4mm 0 2mm;}
.q{font-family:Arial,Helvetica,sans-serif;font-size:10pt;margin:2mm 0 1mm;}
.q .n{font-weight:700;color:#0f766e;}
.op{font-family:Arial,Helvetica,sans-serif;font-size:9.5pt;margin-left:7mm;}
.ln{border-bottom:0.8pt solid #888;height:6.5mm;}
.ln-alta{border-bottom:0.8pt solid #888;height:9mm;}
.fuente{font-family:Arial,Helvetica,sans-serif;font-size:8.5pt;color:#555;font-style:italic;}
.pauta{page-break-before:always;}
.pl{font-family:Arial,Helvetica,sans-serif;font-size:9pt;margin-bottom:1.6mm;text-align:justify;}
.pie{border-top:0.8pt solid #999;margin-top:5mm;padding-top:2mm;font-family:Arial,Helvetica,sans-serif;font-size:8.5pt;color:#555;display:flex;justify-content:space-between;gap:6mm;}
${FaroMarcador.cssImpresion()}
</style></head><body>${cuerpo}<div class="pie"><span>🏠 Proyecto Educativo F.A.R.O. · Estudio Mayor</span><span>🔬 El bisturí de Freeden${pieExtra||''}</span></div></body></html>`;
}
function _abreImpresion(doc){
  const win=window.open('','_blank','');
  if(!win){showToast('⚠️ Activa las ventanas emergentes para imprimir');return;}
  win.document.write(doc);win.document.close();setTimeout(()=>win.print(),400);
}
function imprimirLectura(clave){
  const meta=LECTURAS_IMPR[clave];const card=document.getElementById('lect-'+clave);
  if(!meta||!card){showToast('⚠️ No se encontró la lectura');return;}
  sfx('click');
  const nota=card.querySelector('.lect-nota');
  const parrafos=[...card.querySelectorAll('.lect-p')].map(p=>'<p class="t">'+p.innerHTML+'</p>').join('');
  const cuerpo=`<div class="ruta"><span>🔬 Ruta de las Gafas a la Vista · Etapa 2 de 7</span><span>Lecturas 📖</span></div>`
    +`<h1>${meta.titulo}</h1><div class="tipo">${meta.tipo}</div>`
    +`<div class="etiqueta">${meta.etiq||'<strong>⚠️ Ejercicio de estilo de la casa, en homenaje.</strong> Este texto <strong>NO es obra de ese autor</strong>: lo escribió el Proyecto Educativo F.A.R.O. imitando su voz, y se declara como pastiche. Regla extra de la casa: <strong>toda obra, fecha y persona citada dentro del texto es real y comprobable</strong>; el único artificio permitido es la voz.'}</div>`
    +`<div class="idline"><span>Lee:</span><span class="r"></span><span>Fecha:</span><span class="r" style="max-width:35mm"></span></div>`
    +(nota?`<p class="fuente">${nota.textContent}</p>`:'')
    +parrafos;
  const _ap=window.FaroLecturas;
  const preg=(_ap&&_ap.preguntasImpresas)?_ap.preguntasImpresas(clave):'';
  const _cuerpo=(_ap&&_ap.etiquetaCareo)?_ap.etiquetaCareo(clave,cuerpo):cuerpo;
  _abreImpresion(_hojaImpresa(meta.titulo,_cuerpo+preg+FaroMarcador.impresionExtra([clave]),' · '+meta.titulo));
}
function imprimirTodasLasLecturas(){
  sfx('click');
  let cuerpo=`<div class="ruta"><span>🔬 Ruta de las Gafas a la Vista · Etapa 2 de 7</span><span>Las seis lecturas 📖</span></div>`
    +`<h1>Las seis lecturas de «El bisturí de Freeden»</h1><div class="tipo">Un cuento, un capítulo de caballerías, un ensayo, dos entrevistas imaginadas y un careo, sobre el mismo instrumento</div>`
    +`<div class="etiqueta"><strong>⚠️ Ejercicios de estilo de la casa, en homenaje.</strong> Los cinco primeros <strong>NO son obra de Jorge Luis Borges, de Miguel de Cervantes Saavedra ni de Yuval Noah Harari</strong>: los escribió el Proyecto Educativo F.A.R.O. imitando sus voces, y se declaran como pastiche. Las dos entrevistas son además ficción declarada: <strong>el encuentro nunca ocurrió</strong>; Michael Freeden, Juan Cruz, Jesús Quintero y Antonio Gala son personas reales, y lo inventado es la conversación. El sexto es un <strong>careo</strong> escrito por la casa sobre una disputa que existe de verdad: no imita a nadie, sus turnos los firman papeles y no personas, y las personas reales se citan en tercera persona como fuentes. Regla extra de la casa: <strong>toda obra, fecha y persona citada dentro de los textos es real y comprobable</strong>; el único artificio permitido es la voz.</div>`;
  ['borges','cervantes','harari','entrevista','gala','debate'].forEach((clave,i)=>{
    const meta=LECTURAS_IMPR[clave];const card=document.getElementById('lect-'+clave);
    if(!card)return;
    const nota=card.querySelector('.lect-nota');
    cuerpo+=(i?'<div style="page-break-before:always;"></div>':'')
      +`<h2>${i+1}. ${meta.titulo}</h2><div class="tipo">${meta.tipo}</div>`
      +(nota?`<p class="fuente">${nota.textContent}</p>`:'')
      +[...card.querySelectorAll('.lect-p')].map(p=>'<p class="t">'+p.innerHTML+'</p>').join('');
  });
  _abreImpresion(_hojaImpresa('Las seis lecturas',cuerpo+FaroMarcador.impresionExtra(null),' · Las seis lecturas'));
}
function imprimirPreguntasLecturas(){
  sfx('click');
  const lineas=(n,alta)=>Array(n).fill('<div class="'+(alta?'ln-alta':'ln')+'"></div>').join('');
  let cuerpo=`<div class="ruta"><span>🔬 Ruta de las Gafas a la Vista · Etapa 2 de 7</span><span>Preguntas de las lecturas 📖</span></div>`
    +`<h1>Preguntas de las seis lecturas</h1><div class="tipo">El bisturí de Freeden · 30 de comprensión lectora, 12 de completar y 12 de análisis complejo</div>`
    +`<div class="idline"><span>Nombre:</span><span class="r"></span><span>Fecha:</span><span class="r" style="max-width:35mm"></span></div>`
    +`<div class="etiqueta">Se responde <strong>con los seis textos delante</strong>: no es un examen de memoria. Las respuestas de las tres secciones van en la <strong>pauta de la última hoja</strong>, así que se resuelve antes de darle la vuelta. Los cinco primeros son <strong>ejercicios de estilo de la casa, no obra de Borges, Cervantes ni Harari</strong>, y las dos entrevistas son imaginadas: <strong>el encuentro nunca ocurrió</strong>. El sexto es un <strong>careo</strong> sobre una disputa real, con los turnos firmados por papeles y no por personas.</div>`;
  cuerpo+='<div class="sec">I. Comprensión lectora (30 preguntas)</div>';
  lectComprensionBank.forEach((q,i)=>{
    cuerpo+=`<div class="q"><span class="n">${i+1}.</span> ${q.q} <span class="fuente">(${q.t})</span></div>`;
    q.o.forEach(o=>{cuerpo+=`<div class="op">${o}</div>`;});
  });
  cuerpo+='<div class="sec">II. Completa la oración (12 preguntas)</div>';
  lectCompletarBank.forEach((d,i)=>{
    cuerpo+=`<div class="q"><span class="n">${i+1}.</span> ${d.q.replace('___','_______________')} <span class="fuente">(${d.t})</span></div>`;
  });
  cuerpo+='<div class="sec">III. Análisis complejo (12 preguntas)</div>';
  lectAnalisisBank.forEach((d,i)=>{
    cuerpo+=`<div class="q"><span class="n">${i+1}.</span> ${d.q}</div>`+lineas(3,true);
  });
  cuerpo+='<div class="pauta"><div class="sec">✅ Pauta completa de respuestas</div>';
  cuerpo+='<div class="pl"><strong>I. Comprensión lectora:</strong> '+lectComprensionBank.map((q,i)=>(i+1)+') '+'abcd'[q.c]).join(' · ')+'</div>';
  cuerpo+='<div class="pl"><strong>II. Completar:</strong> '+lectCompletarBank.map((d,i)=>(i+1)+') '+d.a).join(' · ')+'</div>';
  cuerpo+='<div class="pl" style="margin-top:2mm;"><strong>III. Análisis complejo (guías de corrección):</strong></div>';
  lectAnalisisBank.forEach((d,i)=>{cuerpo+=`<div class="pl"><strong>${i+1}.</strong> ${d.guia}</div>`;});
  cuerpo+='</div>';
  _abreImpresion(_hojaImpresa('Preguntas de las lecturas',cuerpo,' · Preguntas de las lecturas'));
}

// ===================== DIPLOMA =====================
function _diplPct(){return xp>=MXP?100:Math.round((xp/MXP)*100);}
function openDiploma(){sfx('fan');const pct=_diplPct();document.getElementById('diplPct').textContent=pct+'%';document.getElementById('diplBar').style.width=pct+'%';document.getElementById('diplDate').textContent='Fecha: '+new Date().toLocaleDateString('es-HN',{year:'numeric',month:'long',day:'numeric'});const msgs=['¡Sigue afilando el bisturí!','¡Muy buen trabajo!','¡Aprendiz de anatomista!','¡Ya distingues núcleo de periferia!','¡Dibujas idearios en una página!'];document.getElementById('diplMsg').textContent=msgs[Math.min(Math.floor(pct/25),4)];const stars=['⭐','⭐⭐','⭐⭐⭐'];document.getElementById('diplStars').textContent=stars[Math.min(Math.floor(pct/40),2)];const achTxt=unlockedAch.map(id=>ACHIEVEMENTS[id].icon+' '+ACHIEVEMENTS[id].label).join(' · ');document.getElementById('diplAch').textContent=achTxt||'Sigue completando secciones para desbloquear logros';document.getElementById('diplomaOverlay').classList.add('open');launchConfetti();}
function closeDiploma(){document.getElementById('diplomaOverlay').classList.remove('open');}
function updateDiplomaName(v){document.getElementById('diplName').textContent=v||'Estudiante';}
function shareWA(){const name=document.getElementById('diplName').textContent||'Estudiante';const pct=_diplPct();const msg='🔬 ¡'+name+' completó la Etapa 2 de la Ruta de las Gafas a la Vista (El bisturí de Freeden)! 🏅 Progreso: '+pct+'% · ⚙️ policastsapien.com';window.open('https://wa.me/?text='+encodeURIComponent(msg),'_blank');}
async function captureDiploma(){if(typeof html2canvas==='undefined'){showToast('⚠️ Cargando... intenta de nuevo');return;}sfx('click');const card=document.querySelector('.diploma-card');const btn=document.querySelector('.diploma-actions .btn-pri');const toHide=[card.querySelector('.diploma-input'),card.querySelector('.diploma-actions'),card.querySelector('hr')];if(btn){btn.disabled=true;btn.textContent='⏳ Capturando...';}toHide.forEach(el=>{if(el)el.style.display='none';});let dataUrl='';try{const canvas=await html2canvas(card,{scale:2,useCORS:true,backgroundColor:'#ffffff'});toHide.forEach(el=>{if(el)el.style.display='';});dataUrl=canvas.toDataURL('image/png');const name=(document.getElementById('diplName').textContent||'Estudiante').replace(/\s+/g,'-');const fileName='constancia-'+name+'.png';const cap=window.Capacitor;if(cap&&cap.isNativePlatform&&cap.isNativePlatform()&&cap.Plugins?.Filesystem&&cap.Plugins?.Share){const base64Data=dataUrl.split(',')[1];const result=await cap.Plugins.Filesystem.writeFile({path:fileName,data:base64Data,directory:'CACHE'});await cap.Plugins.Share.share({url:result.uri,dialogTitle:'Guardar / Compartir Constancia'});}else{const a=document.createElement('a');a.href=dataUrl;a.download=fileName;a.click();}}catch(e){toHide.forEach(el=>{if(el)el.style.display='';});if(e.name!=='AbortError')showToast('⚠️ No se pudo guardar la constancia');}finally{if(btn){btn.disabled=false;btn.textContent='📷 Guardar foto';}}}

